package tryon

import (
	"context"

	"github.com/gogf/gf/v2/frame/g"
	"github.com/gogf/gf/v2/net/ghttp"

	"backend/api/tryon/v1"
	"backend/internal/imagevalidate"
	"backend/internal/logic/tryon"
	"backend/internal/middleware"
	"backend/internal/security"
)

type ControllerV1 struct{}

func NewV1() *ControllerV1 {
	return &ControllerV1{}
}

func (c *ControllerV1) Tryon(ctx context.Context, req *v1.TryonReq) (res *v1.TryonRes, err error) {
	r := ghttp.RequestFromCtx(ctx)
	secService := security.GetService()
	imgLimits := imagevalidate.LoadImageLimits(ctx)

	// 1. 严格校验两张图片（人像和服装）真实格式、文件大小、尺寸及像素
	personImg, garmentImg, imgErr := imagevalidate.ValidateImagesPair(req.PersonImage, req.GarmentImage, imgLimits)
	if imgErr != nil {
		if apiErr, ok := imgErr.(*security.APIError); ok {
			middleware.WriteAPIError(r, apiErr)
			return nil, nil
		}
		middleware.WriteAPIError(r, security.ErrInvalidImageBase64)
		return nil, nil
	}

	// 2. 检查并原子扣减每日调用额度
	// principalID 默认是 Token 哈希；若该 Token 配置了额度命名空间，则改用命名空间名，
	// 使同一合作方轮换 Token 时额度池保持连续。
	principal := security.ResolvePrincipal(r.GetCtxVar(middleware.CtxPrincipalID).String(), secService.NamespaceIndex)
	principalID := principal.ID
	if !secService.DailyQuotaTracker.CheckAndDeduct(principalID) {
		middleware.WriteAPIError(r, security.ErrDailyQuotaExceeded)
		return nil, nil
	}

	// 3. 并发控制（单 Token 并发与全局并发）
	release, ok := secService.ConcurrencyManager.Acquire(principalID)
	if !ok {
		middleware.WriteAPIError(r, security.ErrConcurrencyLimited)
		return nil, nil
	}
	defer release()

	// 服务间调用：显式声明时强制走服务端预设模型，忽略请求体中的 client_config，
	// 避免个人 Key 经由服务端转发链路外发或被记录。
	if req.ServerSide {
		if req.ClientConfig != nil {
			middleware.WriteAPIError(r, security.ErrClientConfigNotAllowed)
			return nil, nil
		}
		if !secService.TokenStore.HasTokens() {
			middleware.WriteAPIError(r, security.ErrServiceCallNotConfigured)
			return nil, nil
		}

		// 所选模型自身未配置密钥/地址时提前拦截，避免落到适配层变成不透明的 500
		if _, cfgErr := tryon.ResolveServerModelConfig(ctx, req.Model); cfgErr != nil {
			g.Log().Infof(ctx, "服务间调用模型未就绪: model=%s err=%v", req.Model, cfgErr)
			middleware.WriteAPIError(r, security.ErrModelNotConfigured)
			return nil, nil
		}

		imageB64, model, prompt, err := tryon.DoTryonWithValidatedImages(
			ctx,
			personImg,
			garmentImg,
			req.Model,
			req.Size,
			req.Lang,
			nil,
		)
		if err != nil {
			return nil, err
		}
		return &v1.TryonRes{
			Image:      imageB64,
			Model:      model,
			Prompt:     prompt,
			ServerSide: true,
		}, nil
	}

	var clientConfig *tryon.ModelConfig
	if req.ClientConfig != nil {
		clientConfig = &tryon.ModelConfig{
			Name:     "browser-custom",
			Provider: req.ClientConfig.Provider,
			APIKey:   req.ClientConfig.APIKey,
			BaseURL:  req.ClientConfig.BaseURL,
			Model:    req.ClientConfig.Model,
		}
	}

	imageB64, model, prompt, err := tryon.DoTryonWithValidatedImages(
		ctx,
		personImg,
		garmentImg,
		req.Model,
		req.Size,
		req.Lang,
		clientConfig,
	)
	if err != nil {
		return nil, err
	}
	return &v1.TryonRes{
		Image:  imageB64,
		Model:  model,
		Prompt: prompt,
	}, nil
}

func (c *ControllerV1) ComfyUIHealth(ctx context.Context, req *v1.ComfyUIHealthReq) (res *v1.ComfyUIHealthRes, err error) {
	model, healthErr := tryon.CheckComfyUI(ctx)
	if healthErr != nil {
		return &v1.ComfyUIHealthRes{
			Available: false,
			Message:   "本地 ComfyUI 或固定工作流不可用",
		}, nil
	}
	return &v1.ComfyUIHealthRes{
		Available: true,
		Model:     model,
		Message:   "本地 ComfyUI 固定工作流可用",
	}, nil
}
